// Two views of n8n's public Feature Requests forum (Discourse JSON):
// the most voted requests and the most recently active ones.
const base = 'https://community.n8n.io/c/feature-requests/5/l/latest.json';
return [
  { json: { view: 'top_voted_p0', url: `${base}?order=votes&page=0` } },
  { json: { view: 'top_voted_p1', url: `${base}?order=votes&page=1` } },
  { json: { view: 'recent_activity', url: `${base}?order=activity&page=0` } },
];

// Flatten, dedupe and keep only the fields the classifier and the ranking need.
const seen = new Set();
const out = [];
for (const page of $input.all()) {
  for (const t of page.json.topic_list?.topics ?? []) {
    if (t.pinned || seen.has(t.id) || /^About the /.test(t.title)) continue;
    seen.add(t.id);
    out.push({ json: {
      id: t.id,
      title: t.title,
      excerpt: (t.excerpt || '').replace(/\s+/g, ' ').slice(0, 600),
      tags: (t.tags || []).map(x => typeof x === 'string' ? x : x.name),
      votes: t.vote_count ?? 0,
      replies: t.reply_count ?? 0,
      views: t.views ?? 0,
      lastActivity: t.last_posted_at,
      url: `https://community.n8n.io/t/${t.slug}/${t.id}`,
    } });
  }
}
return out;

// Build one Jev request per feature request. Three independent judgments over the same state,
// asked together so they run in parallel: product area (choice), enterprise impact (score),
// and whether it looks like a one-off (noul).
const QUESTIONS = {
  "theme": {
    "type": "choice",
    "instructions": "Which product area does this n8n feature request belong to? Judge by the need described in `title` and `excerpt`, not by the words used.",
    "criteria": {
      "identity_access": "Single sign-on, SAML, OIDC, LDAP, SCIM, user provisioning, roles, permissions or project-level access control",
      "governance_compliance": "Audit logs, data retention, data residency, compliance, approvals or policy controls over what workflows can do",
      "credentials_secrets": "Managing, sharing, selecting or securing credentials and secrets, including external secret stores",
      "environments_devops": "Source control, dev/staging/prod environments, deployment, versioning, CI/CD, scaling, queue mode or high availability",
      "observability_reliability": "Execution logs, monitoring, alerting, tracing, token usage, retries and error handling for production workflows",
      "ai_agents": "AI agents, LLM, RAG or evaluation features",
      "integrations_nodes": "A new node or integration with a specific external service, or new options on an existing node",
      "editor_experience": "Canvas, editor, expressions, debugging or general usability for people building workflows",
      "other": "None of the above"
    }
  },
  "enterprise_impact": {
    "type": "score",
    "instructions": "How much does this request matter to a company that runs n8n as shared infrastructure across teams?",
    "criteria": [
      "Mostly matters to individual builders or hobby projects",
      "Useful for small teams, but not a factor in company-wide adoption",
      "Important for companies running n8n in production across several teams",
      "Can block adoption, a security review or a renewal at large or regulated companies"
    ]
  },
  "one_off": {
    "type": "noul",
    "instructions": "Is this a need tied to one specific company's setup or one niche tool, that few other organizations would share?"
  }
};
return $input.all().map(it => ({ json: {
  ...it.json,
  jevRequest: {
    model: 'jev-latest',
    state: { title: it.json.title, excerpt: it.json.excerpt, tags: it.json.tags },
    questions: QUESTIONS,
  },
} }));

// Policy lives in code, judgments come from Jev. Change weights here without re-running inference.
// Demand = distinct people asking (votes) plus discussion, on a log scale so one loud thread can't win alone.
// Only impact above "useful for small teams" (score 1) counts as enterprise demand.
const topics = $('Prepare Jev requests').all().map(i => i.json);
const rows = $input.all().map((it, i) => {
  const t = topics[i];
  const a = it.json.answers || {};
  const impact = a.enterprise_impact?.score ?? 0;            // 0..3
  const oneOff = a.one_off?.noul ?? 0;                        // 0..1
  const theme = a.theme?.choice ?? 'other';
  const demand = Math.log2(1 + t.votes + 0.5 * t.replies);
  const priority = demand * Math.max(0, impact - 1) / 2 * (1 - 0.7 * oneOff);
  const flags = [];
  if ((a.theme?.confidence ?? 1) < 0.5) flags.push('area unclear: human review');
  if (oneOff > 0.6 && impact >= 1.5) flags.push('looks one-off: workaround or partner, not roadmap');
  if (t.votes < 3 && impact >= 2.3) flags.push('high impact, little demand yet: validate with customers');
  return { ...t, theme, themeConfidence: a.theme?.confidence, impact: +impact.toFixed(2), oneOff: +oneOff.toFixed(2),
           demand: +demand.toFixed(2), priority: +priority.toFixed(2), flags };
});
const themes = {};
for (const r of rows) {
  const g = themes[r.theme] ??= { theme: r.theme, priority: 0, requests: 0, votes: 0, top: [] };
  g.priority += r.priority; g.requests++; g.votes += r.votes; g.top.push(r);
}
const ranked = Object.values(themes)
  .map(g => ({ ...g, priority: +g.priority.toFixed(1), top: g.top.sort((x, y) => y.priority - x.priority).slice(0, 3) }))
  .sort((x, y) => y.priority - x.priority);
const sayNo = rows.filter(r => r.flags.some(f => f.startsWith('looks one-off'))).sort((x, y) => y.votes - x.votes).slice(0, 5);
const review = rows.filter(r => r.flags.length && !sayNo.includes(r)).slice(0, 6);
return [{ json: { generatedAt: new Date().toISOString(), analyzed: rows.length, themes: ranked, sayNo, review, rows } }];

// Weekly digest in Markdown: GitHub renders it with tables and links, so the report is shareable as a URL.
const d = $json;
const date = d.generatedAt.slice(0, 10);
const area = t => t.replace(/_/g, ' ');
const cell = s => String(s).replace(/\|/g, '\\|');
const link = r => `[${cell(r.title)}](${r.url})`;
const o = [];
o.push(`<picture><source media="(prefers-color-scheme: dark)" srcset="https://raw.githubusercontent.com/quequegerones/n8n-enterprise-demand-digest/main/assets/n8n-logo-white-accent.png"><img src="https://raw.githubusercontent.com/quequegerones/n8n-enterprise-demand-digest/main/assets/n8n-logo-black-accent.png" alt="n8n" height="28"></picture>`, '', `# Enterprise demand digest, week of ${date}`, '', '*Independent analysis of n8n\'s public feature-request forum. Not affiliated with n8n.*', '');
o.push(`${d.analyzed} feature requests from the [n8n community forum](https://community.n8n.io/c/feature-requests/5), classified with Jev (TypeSafe) and ranked by distinct demand × enterprise impact.`, '');
o.push('## Where enterprise demand concentrates', '', '| # | Area | Priority | Requests | Votes | Top request |', '|---|---|---|---|---|---|');
d.themes.filter(g => g.priority > 0).slice(0, 6).forEach((g, i) =>
  o.push(`| ${i + 1} | **${area(g.theme)}** | ${g.priority} | ${g.requests} | ${g.votes} | ${g.top[0] ? link(g.top[0]) : ''} |`));
const top = [...d.rows].filter(r => r.priority > 0).sort((a, b) => b.priority - a.priority).slice(0, 10);
o.push('', '## Top 10 roadmap candidates', '', '| Request | Area | Impact (0 to 3) | Votes | Priority |', '|---|---|---|---|---|');
for (const r of top) o.push(`| ${link(r)} | ${area(r.theme)} | ${r.impact} | ${r.votes} | ${r.priority} |`);
if (d.sayNo.length) {
  o.push('', '## Probably not roadmap', '', 'Needs tied to one setup or a niche tool: answer with a workaround, a template or a community node.', '');
  for (const r of d.sayNo) o.push(`- ${link(r)} (${r.votes} votes)`);
}
if (d.review.length) {
  o.push('', '## Needs a human look', '');
  for (const r of d.review) o.push(`- ${link(r)}: ${r.flags.join('; ')}`);
}
const quiet = ['identity_access', 'governance_compliance'].filter(t => !((d.themes.find(g => g.theme === t)?.priority ?? 0) > 1));
if (quiet.length) {
  o.push('', `## Low forum signal: ${quiet.map(area).join(' and ')}`, '', `Almost no forum demand for ${quiet.map(area).join(' and ')}. Two readings: much of it already ships (SSO and LDAP, environments and Git version control on Business; audit logging, log streaming and external secret stores on Enterprise, per [n8n.io/pricing](https://n8n.io/pricing/)), and buyers who need more raise it in sales calls and support tickets rather than on a public forum. To tell them apart, the next input for this workflow would be CRM deal notes and support tickets, weighted by account size.`);
}
o.push('', '---', '', '*Method: votes and replies from community.n8n.io. Jev answers three typed questions per request: product area (choice), enterprise impact (score 0 to 3) and one-off probability (yes/no). Priority = log2(1 + votes + replies/2) × max(0, impact − 1)/2 × (1 − 0.7 × one-off). Weights live in code and can change without re-running the model.*');
return [{ json: { date, path: `reports/${date}.md`, markdown: o.join('\n') } }];

// One row per request for the backlog sheet. Upserted by id, so each run refreshes votes, scores and the recommendation.
const d = $json;
return d.rows.map(r => ({ json: {
  id: String(r.id), title: r.title, theme: r.theme.replace(/_/g, ' '),
  enterprise_impact: r.impact, one_off: r.oneOff, votes: r.votes, replies: r.replies, priority: r.priority,
  recommendation: r.flags.some(f => f.startsWith('looks one-off')) ? 'Not roadmap: workaround or partner'
    : r.flags.length ? 'Review' : r.priority >= 2 ? 'Roadmap candidate' : 'Monitor',
  flags: r.flags.join('; '), url: r.url, last_activity: (r.lastActivity || '').slice(0, 10), last_seen: d.generatedAt.slice(0, 10),
} }));

