// Guard for public runs: at most one fresh run per hour. Otherwise serve the last report (no Jev calls).
const store = $getWorkflowStaticData('global');
const fresh = store.v === 4 && store.lastRunAt && (Date.now() - store.lastRunAt) < 60 * 60 * 1000;
if (!fresh) return [{ json: { cached: false } }];
const fmt = t => new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Madrid', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZoneName: 'short' }).format(new Date(t));
const ago = Math.max(1, Math.round((Date.now() - store.lastRunAt) / 60000));
const wait = Math.max(1, 60 - ago);
const banner = '<div class="banner cached">Showing the report from a run ' + ago + ' min ago (' + fmt(store.lastRunAt) + '). To save model calls, live runs are limited to one per hour; the next fresh run is available in about ' + wait + ' min (' + fmt(store.lastRunAt + 3600000) + ').</div>';
return [{ json: { cached: true, page: store.lastHead + banner + store.lastBody } }];

// Wrap the rendered report for the form's completion screen and cache it for an hour.
const sheet = 'YOUR_SHEET_URL';
const repo = 'YOUR_REPO_URL';
const now = Date.now();
const fmt = t => new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Madrid', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZoneName: 'short' }).format(new Date(t));
const head = '<style>.digest{font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:14px;line-height:1.5;color:#1f2937;text-align:left;max-width:960px;margin:0 auto;padding:8px 16px}'
  + '.digest h1{font-size:24px;margin:8px 0 4px}.digest h2{font-size:18px;margin:24px 0 8px;border-bottom:1px solid #e5e7eb;padding-bottom:4px}'
  + '.digest table{border-collapse:collapse;width:100%;margin:8px 0}.digest th{background:#f3f4f6;text-align:left}'
  + '.digest th,.digest td{border:1px solid #e5e7eb;padding:6px 8px;vertical-align:top}.digest a{color:#ea4b71}.digest ul{padding-left:20px}'
  + '.digest .meta{color:#6b7280;font-size:13px}.digest em{color:#6b7280}'
  + '.banner{max-width:928px;margin:0 auto 8px;padding:8px 12px;border-radius:6px;font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:13px;text-align:left}'
  + '.banner.fresh{background:#ecfdf5;color:#065f46}.banner.cached{background:#fffbeb;color:#92400e}</style>';
const body = '<div class="digest"><p class="meta">Backlog: <a href="' + sheet + '" target="_blank">Google Sheet</a> · Code and weekly reports: <a href="' + repo + '" target="_blank">GitHub</a></p>' + $json.html + '</div>';
const store = $getWorkflowStaticData('global');
store.v = 4; store.lastRunAt = now; store.lastHead = head; store.lastBody = body;
const banner = '<div class="banner fresh">Fresh run, just now (' + fmt(now) + '): forum data fetched and every request classified with Jev for you.</div>';
return [{ json: { page: head + banner + body } }];
